import {FT,unproject} from './geometry.mjs';
import {getWalls,validateOpening} from './walls.mjs';
export function setupWallEditor({getState,checkpoint,render,showDialog}){
 const button=document.createElement('button');button.id='wallEditor';button.textContent='Walls, doors & windows';document.querySelector('#addPart').after(button);
 const field=(id,label,value)=>`<label>${label}<input id="${id}" type="number" step="0.125" value="${value}"></label>`;
 button.onclick=()=>{
  showDialog('Walls, doors & windows','<p class="muted">Add walls independently or start a new wall from an existing wall endpoint. All dimensions are feet. Doors and windows are measured from the selected wall’s start.</p><h3>Add a wall</h3><label>Start position<select id="wallAnchor"><option value="free">Typed X/Y position</option></select></label><label>Wall name<input id="newWallName" value="New wall" maxlength="80"></label><div class="form-grid">'+field('newWallX','Start X (ft)',0)+field('newWallY','Start Y (ft)',0)+field('newWallLength','Length (ft)',20)+field('newWallHeight','Wall height (ft)',10)+field('newWallDirection','Direction (degrees: 0 = east, 90 = north)',0)+'</div><button id="addWallNow" class="primary full">Add wall</button><h3>Edit existing wall / add opening</h3><label>Wall<select id="openingWall"></select></label><p id="wallInfo" class="source"></p><div class="form-grid"><label>Opening type<select id="openingKind"><option>Door</option><option>Window</option></select></label>'+field('openingOffset','Distance from wall start (ft)',2)+field('openingWidth','Opening width (ft)',3)+field('openingHeight','Opening height (ft)',7)+field('openingSill','Bottom above floor (ft)',0)+'</div><button id="addOpeningNow" class="primary full">Add door / window</button><div id="openingList"></div><button id="deleteStandaloneWall" class="danger full">Remove selected standalone wall</button><p id="wallEditorFeedback" role="status"></p>');
  const $=id=>document.getElementById(id),value=id=>Number($(id).value),feedback=message=>$('wallEditorFeedback').textContent=message;
  const refresh=()=>{const previous=$('openingWall').value,walls=getWalls(getState());$('wallAnchor').replaceChildren(new Option('Typed X/Y position','free'));$('openingWall').replaceChildren();for(const wall of walls){$('openingWall').add(new Option(wall.name,wall.id));$('wallAnchor').add(new Option(wall.name+' — start',wall.id+'|start'));$('wallAnchor').add(new Option(wall.name+' — end',wall.id+'|end'))}if(walls.some(w=>w.id===previous))$('openingWall').value=previous;details()};
  const details=()=>{const state=getState(),wall=getWalls(state).find(w=>w.id===$('openingWall').value);$('wallInfo').textContent=wall?`${wall.widthFeet.toFixed(2)} ft long × ${wall.height} ft high`:'Add a building section or standalone wall first.';$('addOpeningNow').disabled=!wall;$('deleteStandaloneWall').disabled=!(state.walls||[]).some(w=>w.id===wall?.id);$('openingList').replaceChildren();for(const o of wall?.openings||[]){const row=document.createElement('p');row.textContent=`${o.kind}: ${o.width} × ${o.height} ft; offset ${o.offset} ft; sill ${o.sill} ft `;const remove=document.createElement('button');remove.textContent='Remove opening';remove.onclick=()=>{checkpoint();getState().wallOpenings=getState().wallOpenings.filter(x=>x.id!==o.id);render();details()};row.append(remove);$('openingList').append(row)}};
  $('openingWall').onchange=details;$('openingKind').onchange=()=>{$('openingHeight').value=$('openingKind').value==='Door'?7:4;$('openingSill').value=$('openingKind').value==='Door'?0:3};
  $('addWallNow').onclick=()=>{try{const state=getState(),length=value('newWallLength'),height=value('newWallHeight'),angle=value('newWallDirection')*Math.PI/180,x=value('newWallX'),y=value('newWallY');if(![length,height,angle,x,y].every(Number.isFinite)||length<1||length>500||height<1||height>200||Math.abs(x)>2000||Math.abs(y)>2000)throw Error('Check wall dimensions and position: length 1–500 ft, height 1–200 ft, X/Y within 2,000 ft.');if((state.walls||[]).length>=100)throw Error('The project supports up to 100 standalone walls.');let a={x:x*FT,y:y*FT};if($('wallAnchor').value!=='free'){const [id,endpoint]=$('wallAnchor').value.split('|'),wall=getWalls(state).find(w=>w.id===id);a=wall[endpoint==='start'?'a':'b']}const id=crypto.randomUUID(),wall={id,name:$('newWallName').value.trim()||'Wall',height,a:unproject(a,state.origin),b:unproject({x:a.x+length*FT*Math.cos(angle),y:a.y+length*FT*Math.sin(angle)},state.origin)};checkpoint();(state.walls||=[]).push(wall);render();refresh();$('openingWall').value=id;details();feedback('Wall added. Select 3D to inspect it.')}catch(error){feedback(error.message)}};
  $('addOpeningNow').onclick=()=>{try{const state=getState(),wall=getWalls(state).find(w=>w.id===$('openingWall').value);if(!wall)throw Error('Select a wall first.');if((state.wallOpenings||[]).length>=200)throw Error('Maximum 200 openings per project.');const opening={id:crypto.randomUUID(),wallId:wall.id,kind:$('openingKind').value,offset:value('openingOffset'),width:value('openingWidth'),height:value('openingHeight'),sill:value('openingSill')};validateOpening(wall,opening,state.wallOpenings||[]);checkpoint();(state.wallOpenings||=[]).push(opening);render();details();feedback('Opening added. Wall area and panel cuts recalculated.')}catch(error){feedback(error.message)}};
  $('deleteStandaloneWall').onclick=()=>{const id=$('openingWall').value;checkpoint();getState().walls=getState().walls.filter(w=>w.id!==id);getState().wallOpenings=(getState().wallOpenings||[]).filter(o=>o.wallId!==id);render();refresh();feedback('Standalone wall removed. Undo can restore it.')};refresh();
 };
}
